def compute(vars):
    value_2016 = vars["v1"] * vars["v2"]
    value_2017 = vars["v3"] * vars["v4"]
    increase = value_2017 - value_2016

    return {
        "value": increase,
        "trace": {
            "value_2016_million_dollars": value_2016,
            "value_2017_million_dollars": value_2017,
            "increase_million_dollars": increase,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "dollars"
            }
        }
    }
